func LookupPslBinaryGo(sfx string) bool {
	t := strings.ToLower(strings.TrimSpace(sfx))
	if t == "" || strings.HasPrefix(t, ".") {
		return false
	}
	idx := sort.Search(len(CompiledPslTable), func(i int) bool {
		return CompiledPslTable[i].Suffix >= t
	})
	return idx < len(CompiledPslTable) && CompiledPslTable[idx].Suffix == t
}
